/* The code segments the game DMAs, for the native port (M2). Host side. On the N64 the resident engine segments
 * (engine1/2/4, evt, entity) and every overlay (maps, battle areas, moves, partners, effects, the pause and file
 * menus) are copied from the ROM into their VRAM windows; natively all of them are linked in, so a DMA of a code
 * segment's range is not a copy (and its "VRAM" destination is no host address). The ranges come from the decomp's
 * splat.yaml (build/game/port_segtab.c, generated by tools/port/gen_build.py). Later: an overlay's data is restored
 * from a pristine copy on each load, as the N64's fresh DMA does (SPIKE.md Q6). */
#include "port.h"

extern const struct { uint32_t start, end; const char *name; } port_code_segs[];
extern const int port_code_segs_n;

int port_code_segment(uint32_t rom_start, uint32_t rom_end, int *seg_index) {
    int lo = 0, hi = port_code_segs_n - 1;
    while (lo <= hi) { /* the table is in ROM order */
        const int mid = (lo + hi) / 2;
        if (rom_start < port_code_segs[mid].start) hi = mid - 1;
        else if (rom_start >= port_code_segs[mid].end) lo = mid + 1;
        else {
            if (rom_end > port_code_segs[mid].end)
                port_log("segments: DMA 0x%08X..0x%08X runs past code segment %s (ends 0x%08X)\n", rom_start, rom_end,
                         port_code_segs[mid].name, port_code_segs[mid].end);
            if (seg_index) *seg_index = mid;
            return 1;
        }
    }
    return 0;
}
